\section{Index of Category Theory} \subsection{Foundamental Concepts and Axioms}
\subsubsection{Basic Definitions} \begin{enumerate} \item category theory \item object \item identity \item arrow \item morphism \item composition law \item commutativity \item associativity \item axioms of category theory \item ETAC \item triples \item Abelian group \item group \item groupoid \item semigroup \item monoid \item ring \item diagram \item precategory \item category \item alternative definition of category \item subcategory \item small category \item category of sets ($Set$, $Ens$) \item automorphism \item commutative diagram \item concrete category \item dual category \item duality principle \item endomorphism \item epi \item monic \item extremal monomorphism \item source \item sink \item initial source \item final sink \item isomorphism-closed subcategory \item locally finite category \item preimage of category \item product of categories \item types of morphisms \item wellpowered category \item zero object \item \PMlinkid{$\mathcal{U}$-small}{5658} \item equalizer \item subobject \item quotient object \item direct product \item direct sum \item pullback \item pushout \item direct limit \item limiting cone \item cocone and colimit functor \item complete category \item groupoid (category theoretic) \end{enumerate}
